\section{স্পার্মিওজেনেসিস (Spermiogenesis)}

\subsection{স্পার্মিওজেনেসিসের ধাপসমূহ (Steps of Spermiogenesis)}

\begin{figure}[h]
    \centering
    \includegraphics[width=0.8\textwidth]{image.png}
    \caption{স্পার্মিওজেনেসিসের ধাপসমূহ}
